"""Authored keyframe motion: distinct attacks, stage defeat and final dissipation."""
from pathlib import Path
import json,math
A=Path(__file__).resolve().parents[1]/'custom_mods/hardcore/src/main/resources/assets/tecnihardcore'
p=A/'animations/custodio.animation.json';d=json.loads(p.read_text('utf8'));an=d['animations']
def track(**keys):return {k.replace('_','.'):v for k,v in keys.items()}
def anim(name,length,bones):an['animation.custodio.'+name]={'loop':False,'animation_length':length,'bones':bones}
def pose(rot=None,pos=None,scale=None):
 out={}
 if rot:out['rotation']=rot
 if pos:out['position']=pos
 if scale:out['scale']=scale
 return out
def arms(left,right):return {'left_arm':pose(left),'right_arm':pose(right)}
anim('melee',.5,{'body':pose(track(**{'0':[0,-14,0],'0_2':[0,-24,-6],'0_3':[14,22,4],'0_5':[0,0,0]})),**arms(track(**{'0':[-18,0,-12],'0_3':[20,0,-5],'0_5':[0,0,0]}),track(**{'0':[-70,-20,32],'0_2':[-115,-25,22],'0_3':[38,28,-18],'0_5':[0,0,0]}))})
anim('slam',2.2,{'body':pose(track(**{'0':[0,0,0],'0_55':[-18,0,0],'0_95':[-25,0,0],'1':[32,0,0],'1_2':[18,0,0],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_85':[0,3,0],'1':[0,-4,0],'1_2':[0,-1,0],'2_2':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_6':[-160,0,-18],'0_95':[-170,0,-18],'1':[38,0,4],'1_3':[12,0,0],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_6':[-160,0,18],'0_95':[-170,0,18],'1':[38,0,-4],'1_3':[12,0,0],'2_2':[0,0,0]}))})
anim('fracture',2.2,{'body':pose(track(**{'0':[0,0,0],'0_7':[-8,-35,0],'1':[18,30,0],'1_25':[12,-8,0],'2_2':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_7':[-80,-15,-50],'1':[30,20,-18],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_7':[-120,20,30],'1':[60,-30,0],'2_2':[0,0,0]}))})
anim('volley',2.2,{'body':pose(track(**{'0':[0,0,0],'0_7':[-12,0,0],'1':[8,0,0],'1_3':[-8,0,0],'1_35':[10,0,0],'2_2':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_6':[-60,0,-55],'0_95':[-80,-25,-25],'1':[-100,0,-8],'1_35':[-90,0,-14],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_6':[-60,0,55],'0_95':[-80,25,25],'1':[-100,0,8],'1_35':[-90,0,14],'2_2':[0,0,0]}))})
anim('meteor',2.8,{'body':pose(track(**{'0':[0,0,0],'0_7':[-18,0,0],'1':[12,0,0],'1_5':[-6,0,0],'2':[10,0,0],'2_8':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_8':[-145,-15,-20],'1':[30,0,-40],'1_5':[-90,0,-15],'2':[20,0,-30],'2_8':[0,0,0]}),track(**{'0':[0,0,0],'0_8':[-145,15,20],'1':[30,0,40],'1_5':[-90,0,15],'2':[20,0,30],'2_8':[0,0,0]}))})
anim('prison',2.2,{'body':pose(track(**{'0':[0,0,0],'0_6':[-10,0,0],'1':[14,0,0],'2_2':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_7':[-85,35,-70],'0_95':[-80,50,-80],'1':[-80,-35,-5],'1_2':[-70,-10,-10],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_7':[-85,-35,70],'0_95':[-80,-50,80],'1':[-80,35,5],'1_2':[-70,10,10],'2_2':[0,0,0]}))})
anim('charge',2.2,{'body':pose(track(**{'0':[0,0,0],'0_7':[32,0,0],'1':[24,0,0],'1_8':[24,0,0],'2_2':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_7':[-65,0,-25],'1':[-80,0,-12],'1_8':[-80,0,-12],'2_2':[0,0,0]}),track(**{'0':[0,0,0],'0_7':[-65,0,25],'1':[-80,0,12],'1_8':[-80,0,12],'2_2':[0,0,0]}))})
stage={'body':pose(track(**{'0':[0,0,0],'0_4':[14,-8,5],'0_8':[45,0,0],'1_6':[55,0,0],'2_2':[-12,0,0],'3_4':[0,0,0],'4':[0,0,0]}),track(**{'0':[0,0,0],'0_8':[0,-10,0],'1_7':[0,-12,0],'2_2':[0,5,0],'3_4':[0,0,0],'4':[0,0,0]})),**arms(track(**{'0':[0,0,0],'0_8':[48,0,-15],'1_7':[42,0,-30],'2_2':[-80,0,-80],'3_4':[0,0,-10],'4':[0,0,0]}),track(**{'0':[0,0,0],'0_8':[48,0,15],'1_7':[42,0,30],'2_2':[-80,0,80],'3_4':[0,0,10],'4':[0,0,0]}))}
for i in range(4):
 a=i*math.pi/2
 stage['orbit_'+str(i)]=pose(track(**{'0':[0,0,0],'1_7':[0,100,40],'2_2':[0,180,80],'3_4':[0,360,0],'4':[0,360,0]}),track(**{'0':[0,0,0],'1_7':[math.cos(a)*10,4,math.sin(a)*10],'2_2':[math.cos(a)*22,12,math.sin(a)*22],'3_4':[0,0,0],'4':[0,0,0]}))
anim('phase_break',4,stage)
transform={'body':pose(track(**{'0':[0,0,0],'0_5':[10,0,8],'1':[48,0,0],'2_6':[60,0,0],'3':[0,0,0],'4_4':[-15,180,0],'5_4':[8,360,0],'6':[0,360,0]}),track(**{'0':[0,0,0],'1':[0,-12,0],'2_6':[0,-12,0],'3':[0,3,0],'4_4':[0,10,0],'5_4':[0,3,0],'6':[0,0,0]})),**arms(track(**{'0':[0,0,0],'1':[40,0,-25],'2_6':[40,0,-70],'3':[-40,0,-45],'4_4':[-90,0,-75],'6':[0,0,0]}),track(**{'0':[0,0,0],'1':[40,0,25],'2_6':[40,0,70],'3':[-40,0,45],'4_4':[-90,0,75],'6':[0,0,0]}))}
for side,sign in [('left',-1),('right',1)]:transform[side+'_wing']=pose(track(**{'0':[0,0,0],'3':[0,sign*60,sign*65],'4_4':[0,sign*-22,sign*-18],'5_4':[0,sign*8,0],'6':[0,0,sign*8]}))
for i in range(4):
 a=i*math.pi/2;transform['orbit_'+str(i)]=pose(track(**{'0':[0,0,0],'2':[0,100,50],'3':[0,160,100],'4_4':[0,360,180],'6':[0,720,0]}),track(**{'0':[0,0,0],'2':[math.cos(a)*14,8,math.sin(a)*14],'3':[math.cos(a)*26,20,math.sin(a)*26],'4_4':[math.cos(a)*12,6,math.sin(a)*12],'6':[0,0,0]}))
anim('transform',6,transform)
death={'body':pose(track(**{'0':[0,0,0],'0_4':[-10,0,5],'1_2':[40,0,0],'2_4':[65,0,0],'3_8':[-18,0,0],'5':[0,180,0],'6':[0,360,0]}),track(**{'0':[0,0,0],'1_2':[0,-12,0],'2_4':[0,-16,0],'3_8':[0,5,0],'5':[0,20,0],'6':[0,26,0]}),track(**{'0':[1,1,1],'3_8':[1,1,1],'4_5':[.8,.8,.8],'5_5':[.06,.06,.06],'6':[.001,.001,.001]}))}
for side,sign in [('left',-1),('right',1)]:
 death[side+'_arm']=pose(track(**{'0':[0,0,0],'1_2':[50,0,sign*20],'3_8':[-60,0,sign*85],'6':[-60,0,sign*150]}),track(**{'0':[0,0,0],'3_8':[sign*8,4,0],'6':[sign*40,20,0]}))
 death[side+'_wing']=pose(track(**{'0':[0,0,0],'2_4':[0,sign*30,sign*45],'3_8':[0,sign*-40,sign*-25],'6':[0,sign*-60,sign*-50]}),track(**{'0':[0,0,0],'3_8':[0,0,0],'6':[sign*32,24,12]}))
for i in range(4):
 a=i*math.pi/2;death['orbit_'+str(i)]=pose(track(**{'0':[0,0,0],'3_8':[0,360,90],'6':[0,720,180]}),track(**{'0':[0,0,0],'3_8':[0,0,0],'6':[math.cos(a)*50,25,math.sin(a)*50]}))
anim('death',6,death)
p.write_text(json.dumps(d,indent=2),encoding='utf8')
print('Nine authored action/defeat clips written; release at normalized 1 second, melee at 0.3.')
